  &DefaultButton;




function filter$hrpermission(p){
  this.constructor(p);
}
filter$hrpermission.prototype = new DirEvent();

filter$hrpermission.prototype.afterInit = function(){
  var p = this._dir, pa = p.options.parent, g = pa.grid(), r = g._currRow, dt = g.data;

  p.valForm(['user_id', 'username', 'nickname'], [dt.val(r, "user_id"), dt.val(r, "username"), dt.val(r, "nickname")]);
  p.request('getHRPermission', 'GetDataSet', ['user_id'], filter$hrpermission$LoadTree);
}

filter$hrpermission.prototype.beforeButtonDialogClick = function(id){
  var p = this._dir;
  if (id == 'filterOk') {
    var tbp = p.find("#hrpermission_1").treeview("instance"), tcn = p.find("#hrpermission_2").treeview("instance");
    p.request('updateRight', '', ['user_id', ['bp', 'C', tbp.getParentCheckedItem()], ['cn', 'C', tcn.getCheckedItem()]], function(p, d, run){
      if (run) p._close();
    });
    return false;
  }
  return true;
}

function filter$hrpermission$LoadTree(p, d){
  var d = new DataSet(d);
  p.find("#hrpermission_1").treeview({ tblData: d.get(0), expandAll: true, onCreated: function(tv) {
      tv.refreshItemCheck();
    }
  });
  p.find("#hrpermission_2").treeview({ tblData: d.get(1), expandAll: true, onCreated: function(tv) {
      tv.refreshItemCheck();
    }
  });
}






.tree-resize{
  display: none;
}

#hrpermission_1, #hrpermission_2 {
  overflow: hidden;
}
#hrpermission_1 > div:first-child, #hrpermission_2 > div:first-child {
  display: none;
}







exec ISWIFTStoredHrGetDepartment '@@lan', @user_id, @@userId, @@admin, 0
exec ISWIFTStoredHrGetEmployeeMenu '@@lan', @user_id, @@userId, @@admin, 1







delete sysrighthrdept2 where user_id = @user_id
if @bp <> ''
  insert into sysrighthrdept2 
	  select @user_id, b.ma_bp, b.bp_ref from dbo.ISWIFTFunction$Split(@bp, ',') a join hrdmbp b ON a.data = b.ma_bp

delete sysrighthremenu2 where user_id = @user_id
if @cn <> ''
  insert into sysrighthremenu2 
	  select @user_id, a.data, b.id from dbo.ISWIFTFunction$Split(@cn, ',') a join hremenu b on left(a.data, len(a.data) - 2) = b.controller

exec ISWIFTStoredUpdateRightHRDepartment @user_id, @@userId, @@admin
exec ISWIFTStoredUpdateRightHRMenu @user_id, @@userId, @@admin
select '' as message
